+func FilterByConfidence(suggestions []core.Suggestion, minConfidence int) []core.Suggestion {
+	out := make([]core.Suggestion, 0, len(suggestions))
+	for _, s := range suggestions {
+		if s.Confidence >= minConfidence {
+			out = append(out, s)
+		}
+	}
+	return out
+}
+
+func SortBySeverity(suggestions []core.Suggestion) []core.Suggestion {
+	out := make([]core.Suggestion, len(suggestions))
+	copy(out, suggestions)
+	sort.SliceStable(out, func(i, j int) bool {
+		ri := rank(out[i].Severity)
+		rj := rank(out[j].Severity)
+		if ri != rj {
+			return ri > rj
+		}
+		return out[i].LineNumber < out[j].LineNumber
+	})
+	return out
+}
